import random, itertools, traceback
from boltons.setutils import IndexedSet, _MISSING

def check_invariants(s, tag):
    items = s.item_list
    dead = s.dead_indices
    missing = {i for i, x in enumerate(items) if x is _MISSING}
    # 1. dead intervals must exactly cover missing slots, be sorted/disjoint
    covered = set()
    prev_stop = -1
    for d_start, d_stop in dead:
        assert d_start < d_stop, (tag, dead)
        assert d_start >= prev_stop, ('overlapping/unsorted', tag, dead)
        prev_stop = d_stop
        covered.update(range(d_start, d_stop))
    assert covered == missing, (tag, 'dead_indices mismatch', sorted(covered), sorted(missing), dead)
    # 2. map points at live slots and matches list(self)
    live = [i for i, x in enumerate(items) if x is not _MISSING]
    for it, phys in s.item_index_map.items():
        assert items[phys] is it and phys in live or items[phys] is it, (tag, it, phys)
    assert sorted(s.item_index_map.values()) == live, (tag, 'map values vs live')
    # 3. round trip apparent<->real
    for a in range(len(s)):
        r = s._get_real_index(a)
        assert 0 <= r < len(items) and items[r] is not _MISSING, (tag, 'real', a, r, dead, items)
        assert s._get_apparent_index(r) == a, (tag, 'roundtrip', a, r, dead)
    # 4. trailing dead must be culled (pop() relies on item_list[-1] being live)
    if s:
        assert items[-1] is not _MISSING, (tag, 'trailing dead survived _cull', dead, items)

def diff_getitem(s, ref, tag):
    n = len(ref)
    for i in list(range(-n-3, n+3)):
        try:
            got = s[i]
        except IndexError:
            if -n <= i < n:
                raise AssertionError((tag, 'unexpected IndexError', i))
            continue
        if not (-n <= i < n):
            raise AssertionError((tag, 'expected IndexError for', i, 'got', got))
        if got != ref[i]:
            raise AssertionError((tag, 'value mismatch', i, got, ref[i]))

rng = random.Random(42)
