        tag = (trial, step, op, list(ref))
        if op == 'remove' and ref:
            v = rng.choice(ref)
            s.remove(v); ref.remove(v)
        elif op == 'popi' and ref:
            i = rng.choice(list(range(-len(ref)-2, len(ref)+2)))
            t = IndexedSet(s); tref = list(ref)
            try:
                got = t.pop(i)
                if not (-len(ref) <= i < len(ref)):
                    raise AssertionError((tag, 'pop: expected IndexError for', i, 'got', got))
                exp = tref.pop(i)
                if got != exp or list(t) != tref:
                    raise AssertionError((tag, 'pop mismatch', i, got, exp, list(t), tref))
            except IndexError:
                if -len(ref) <= i < len(ref):
