from boltons.setutils import IndexedSet, _MISSING
import random

fails = []

def check_state(iset, ref, tag):
    if list(iset) != ref: fails.append(('contents', tag, list(iset)[:20], ref[:20]))
    if list(iset.item_list).count(_MISSING) != iset._dead_index_count:
        fails.append(('deadcount', tag))
    # every live item's map index must point at itself; dead slots consistent
    il = iset.item_list; im = iset.item_index_map
    for k, v in im.items():
        if v >= len(il) or il[v] is not k or il[v] is _MISSING:
            fails.append(('map', tag, k, v)); return
    nmiss = sum(1 for x in il if x is _MISSING)
    if len(il) - len(im) != nmiss: fails.append(('miss', tag, len(il), len(im), nmiss))

# Big sets with few removals -> dead slots persist (no compaction)
random.seed(11)
for n in (50, 100, 500):
    for remove_idx in ([0], [n-1], [n//2], [0, n//2, n-1], [n//4, n//4+1, n//2],
                       list(range(3)), [n-1, n-2], sorted(random.sample(range(n), min(6, n)))):
        iset = IndexedSet(range(n))
        ref = list(range(n))
        for i in remove_idx:
            iset.remove(ref[i]) if False else None
        # remove by value
        iset = IndexedSet(range(n)); ref = list(range(n))
        for i in remove_idx:
            v = ref.pop(i); iset.remove(v)
        if iset.dead_indices and iset._dead_index_count > len(iset.item_list)/8:
            # compaction would kick in; skip those (internal state differs by design)
            pass
        check_state(iset, ref, 'init')
        # exhaustive getitem
        for i in range(-len(ref)-3, len(ref)+3):
            try: g = repr(iset[i])
            except IndexError: g = 'IndexError'
            except Exception as e: g = 'EXC:' + type(e).__name__
            try: e = repr(ref[i])
            except IndexError: e = 'IndexError'
            if g != e: fails.append(('getitem', n, remove_idx, i, g, e))
        # exhaustive pop probe (restore each time)
        for i in range(-len(ref)-3, len(ref)+3):
            sl = (list(iset.item_list), dict(iset.item_index_map), [list(x) for x in iset.dead_indices])
            try: g = repr(iset.pop(i))
            except IndexError: g = 'IndexError'
            except Exception as e: g = 'EXC:' + type(e).__name__
            after = (list(iset.item_list), dict(iset.item_index_map), [list(x) for x in iset.dead_indices])
            iset.item_list[:] = sl[0]; iset.item_index_map.clear(); iset.item_index_map.update(sl[1]); iset.dead_indices[:] = sl[2]
            try: e = repr(ref[i])
            except IndexError: e = 'IndexError'
            if g != e: fails.append(('pop', n, remove_idx, i, g, e))
            if g == 'IndexError' and after != sl: fails.append(('mut_on_err', n, remove_idx, i))
        # drain from the end AND from the front, compare vs list
        ref2, iset2 = list(ref), IndexedSet(iset)
        # pop last repeatedly
        while ref2:
            a = iset2.pop(); b = ref2.pop()
            if a != b: fails.append(('drain_last', n, remove_idx, a, b))
        check_state(iset2, [], 'drained_last')
        # pop first repeatedly
        ref3, iset3 = list(ref), IndexedSet(iset)
        while ref3:
            a = iset3.pop(0); b = ref3.pop(0)
            if a != b: fails.append(('drain_first', n, remove_idx, a, b))
        check_state(iset3, [], 'drained_first')
        # pop middle repeatedly
        ref4, iset4 = list(ref), IndexedSet(iset)
        while ref4:
            k = len(ref4)//2
            a = iset4.pop(k); b = ref4.pop(k)
            if a != b: fails.append(('drain_mid', n, remove_idx, a, b))
        check_state(iset4, [], 'drained_mid')

# interleaved add/remove/pop on big set
random.seed(23)
for trial in range(50):
