function probesFor(range) {
  const out = new Set()
  let r
  try { r = new Range(range) } catch (e) { return out }
  for (const set of r.set) for (const c of set) {
    if (!c.semver || typeof c.semver === 'symbol') continue
    const { major: M, minor: m, patch: p } = c.semver
    out.add(c.semver.version)
    const tuples = [
      [M, m, p], [M, m, p + 1], [M, m + 1, 0], [M + 1, 0, 0],
      ...(p > 0 ? [[M, m, p - 1]] : []),
      ...(m > 0 ? [[M, m - 1, p]] : []),
      ...(M > 0 ? [[M - 1, m, p]] : []),
