const tuples = [[0,5,0],[1,0,0],[1,1,0],[1,2,0],[1,2,3],[1,3,0],[2,0,0],[5,0,0],[5,9,0],[6,0,0],[6,1,0],[6,2,0],[6,3,0],[6,3,1],[6,3,2],[6,4,0],[6,9,0],[7,0,0],[7,1,0]];
